// Rebuild the checked-in fork from the unmodified, attributed upstream bundle.
// No build step or dependency is needed when running main.ts.
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';
import { Lexer } from '../vendor/marked/marked.esm.js';

const upstream = new URL('../vendor/marked/marked.esm.js', import.meta.url);
let source = readFileSync(upstream, 'utf8');
const revision = Number(process.argv[2] ?? 2);
const output = process.argv[3] ? resolve(process.argv[3]) : new URL('../parse.js', import.meta.url);
const digest = createHash('sha256').update(source).digest('hex');
if (digest !== 'e76f3b37046a5d294159872002e5f6fcda8ed232e1be45ff76b3863f2919dae3') {
  throw new Error('Unexpected marked source; review patches against this version.');
}

function replaceOnce(before, after) {
  if (source.split(before).length !== 2) {
    throw new Error(`Patch must match exactly once: ${before}`);
  }
  source = source.replace(before, () => after);
}

replaceOnce(' * DO NOT EDIT THIS FILE', ' * Optimized default-options fork; rebuild with node tools/build-fork.mjs.');
if (revision >= 1) {
replaceOnce('let i;if(this.options.extensions?.inline',
  'let i,first=e.charCodeAt(0);if(this.options.extensions?.inline');

// Every guarded rule is anchored. These are necessary leading characters in
// the upstream default grammar, so skipping the other probes cannot match less.
const guards = {
  escape: 'first===92',
  tag: 'first===60',
  link: '(first===91||first===33)',
  reflink: '(first===91||first===33)',
  emStrong: '(first===42||first===95)',
  codespan: 'first===96',
  br: '(first===32||first===92)',
  del: 'first===126',
  autolink: 'first===60',
};
for (const [method, guard] of Object.entries(guards)) {
  const args = method === 'reflink' ? 'e,this.tokens.links'
    : method === 'emStrong' || method === 'del' ? 'e,t,r' : 'e';
  replaceOnce(`if(i=this.tokenizer.${method}(${args}))`,
    `if(${guard}&&(i=this.tokenizer.${method}(${args})))`);
}

// Profile revision 1: GFM text's email lookaheads still scan ordinary words.
}
// If the entire inline source has no @, neither email alternative can match
// any suffix. Remove just those alternatives; retain all other text rules.
if (revision >= 2 && !process.argv.includes('--without-email')) {
let noEmailText = new Lexer().tokenizer.rules.inline.text.source;
// The literals below are matched against RegExp.source, not Markdown input.
const emailClass = String.raw`a-zA-Z0-9.!#$%&'*+\/=?_` + '`' + String.raw`{\|}~-`;
for (const alternative of [
  `|(?=[${emailClass}]+@)`,
  `|[^${emailClass}](?=[${emailClass}]+@)`,
]) {
  if (noEmailText.split(alternative).length !== 2) {
    throw new Error(`Email alternative must match exactly once: ${alternative}`);
  }
  noEmailText = noEmailText.replace(alternative, '');
}
replaceOnce('inlineText(e){let t=this.rules.inline.text.exec(e);',
  'inlineText(e,noEmail){let t=(noEmail?fastTextNoEmail:this.rules.inline.text).exec(e);');
replaceOnce('#t(e,t,n){let s=!1,r="",o=1/0;',
  '#t(e,t,n){let noEmail=!e.includes("@"),s=!1,r="",o=1/0;');
replaceOnce('if(i=this.tokenizer.inlineText(l))',
  'if(i=this.tokenizer.inlineText(l,noEmail))');
replaceOnce('if(!this.state.inLink&&(i=this.tokenizer.url(e)))',
  'if(!this.state.inLink&&(!noEmail||first===104||first===72||first===102||first===70||first===119)&&(i=this.tokenizer.url(e)))');
source += `\n// Email branches cannot match sources without an at sign.\nconst fastTextNoEmail = new RegExp(${JSON.stringify(noEmailText)});\n`;
}

if (revision >= 3) {
  // The list tokenizer only wants the prefix before the first LF. Avoid split's
  // result arrays and generic separator machinery for each scanned list line.
  replaceOnce('t[2].split(`\n`,1)[0]', 'fastFirstLine(t[2])');
  const expression = 'e.split(`\n`,1)[0]';
  if (source.split(expression).length !== 3) throw new Error('Expected two list line probes.');
  source = source.replaceAll(expression, 'fastFirstLine(e)');
  source += '\nfunction fastFirstLine(src) { const end = src.indexOf("\\n"); return end < 0 ? src : src.slice(0, end); }\n';
}

// Expose only the requested default-options renderer; callers cannot mutate it.
source = source.replace(/export\{[^;]+\};/, 'export {x as parse};')
  .replace('//# sourceMappingURL=marked.esm.js.map', '');
writeFileSync(output, source);
